import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Governing Board- Public Session 2026-08-25","description":"","frontmatter":{"title":"Ceph Governing Board- Public Session 2026-08-25","date":"2026-08-25T00:00:00.000Z","updated":"2026-08-26T00:00:00.000Z","tags":["社区动态","会议纪要","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-08-25.md","filePath":"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-08-25.md","lastUpdated":null}'),o={name:"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-08-25.md"};function n(h,t,i,l,s,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议为 Ceph 基金会（Ceph Foundation，简称 SEF）理事会 2026 年 8 月 25 日公开例会，涵盖预算更新、社区管理、文档进展、Ceph Days 活动安排等议题。</p><h2 id="会议纪要审批" tabindex="-1">会议纪要审批 <a class="header-anchor" href="#会议纪要审批" aria-label="Permalink to &quot;会议纪要审批&quot;">​</a></h2><p>与会成员对 7 月 28 日公开会议纪要进行了投票，由 Stephen 提出动议，另一位成员附议，无反对票，无弃权票，动议通过。</p><h2 id="预算更新" tabindex="-1">预算更新 <a class="header-anchor" href="#预算更新" aria-label="Permalink to &quot;预算更新&quot;">​</a></h2><p>当前预算状况健康：</p><ul><li>无超支预期</li><li>收入按计划推进，且因新成员加入而表现优于预期</li><li>九月份预算工作将在私有会议中正式启动</li></ul><h2 id="社区经理报告-anthony" tabindex="-1">社区经理报告（Anthony） <a class="header-anchor" href="#社区经理报告-anthony" aria-label="Permalink to &quot;社区经理报告（Anthony）&quot;">​</a></h2><p><strong>基金会宣传材料</strong></p><p>Anthony 在上次会议中分享了基金会宣传 pitch deck，并获得了 Niha 在技术历史与版本更新方面的协助支持。该 deck 目前状态良好，计划面向有意使用 Ceph 及与基金会合作的外部组织进行推广宣传。</p><p><strong>Ceph Developer Summit</strong></p><p>近期围绕 Ceph（即字幕中 &quot;vampire&quot; 相关部分）举办的开发者峰会历时约两周，所有会议均已录制，并发布至 Ceph 官方 YouTube 频道及官网活动页面。</p><p><strong>Q3 CSC 与基金会理事会联席会议</strong></p><p>会议定于 9 月 23 日上午 11:00 EST 举行。请各与会方在 9 月 16 日前将议题或问题提交至 etherpad，以便提前整理议程并分发给所有人。</p><p><strong>ceph.io 网站维护</strong></p><p>Anthony 注意到网站存在若干过期内容，包括行为准则（Code of Conduct）、商标条款及使用条款等。计划如下：</p><ul><li>Ben 将主导商标相关的使用条款与隐私政策更新，以独立 PR 形式提交</li><li>行为准则将另开 PR 单独处理</li><li>高质量 Ceph Days 品牌图片（SVG 格式）的制作请求将提交至 LF，由 Ben 协助跟进</li></ul><h2 id="文档团队报告-manuel" tabindex="-1">文档团队报告（Manuel） <a class="header-anchor" href="#文档团队报告-manuel" aria-label="Permalink to &quot;文档团队报告（Manuel）&quot;">​</a></h2><p>Manuel 对错过上次会议表示歉意，并汇报了文档工作的最新进展：</p><p><strong>工作阶段</strong></p><p>文档清理工作分四个阶段推进，目前处于第三阶段：</p><ol><li>识别技术债（Tech Debt）— 已完成</li><li>修复高危问题 — 已完成</li><li>补全缺失、不完整或不准确的内容 — <strong>进行中</strong></li><li>第四阶段待定</li></ol><p><strong>当前进展</strong></p><ul><li>已关闭 27 个 issue</li><li>所有 issue 在 tracker.ceph.com 中按&quot;documentation&quot;标签跟踪，进度公开可查</li><li>仍有约 40 余个 issue 待处理</li></ul><p><strong>ceph.io 网站协作</strong></p><p>Manuel 与 Anthony 共同对 ceph.io 进行了大规模更新，新增了快速链接、文档入口以及新内容，并对网站上大量过时信息进行了修订。Manuel 对社区（包括 Anthony、Deatri 及文档团队其他成员）在审查和引导方面给予的支持表示感谢。</p><h2 id="委员会事项" tabindex="-1">委员会事项 <a class="header-anchor" href="#委员会事项" aria-label="Permalink to &quot;委员会事项&quot;">​</a></h2><h3 id="ceph-days-活动" tabindex="-1">Ceph Days 活动 <a class="header-anchor" href="#ceph-days-活动" aria-label="Permalink to &quot;Ceph Days 活动&quot;">​</a></h3><p>当前已确认及规划中的 Ceph Days 活动共 8 场（相比 2025 年的 6 场和 2024 年的 5 场有所增长），分布如下：</p><table tabindex="0"><thead><tr><th>活动</th><th>时间</th><th>地点</th><th>备注</th></tr></thead><tbody><tr><td>Ceph Day Korea</td><td>9 月 1 日</td><td>韩国</td><td>与另外两个开源项目联合举办，由 Ceph Ambassador 主导</td></tr><tr><td>Ceph Day Zurich</td><td>10 月</td><td>瑞士苏黎世</td><td>详情待定</td></tr><tr><td>Ceph Day Australia</td><td>10 月</td><td>澳大利亚</td><td>由 Ceph Ambassador 主导，寻求赞助支持</td></tr><tr><td>Ceph Day Chicago</td><td>11 月</td><td>美国芝加哥</td><td>与 Supercomputing 大会同期举办</td></tr><tr><td>其他场次</td><td>2027 年</td><td>待定</td><td>规划中</td></tr></tbody></table><p><strong>商标合规说明</strong></p><p>随着 Ceph 商标事宜的推进，凡使用 Ceph 商标的官方活动均需完成简单的商标审查流程。若活动涉及个人信息（PII）收集（如活动注册），须使用 LF 指定平台 Reggeox 进行处理，以确保符合隐私政策要求（该平台免费）。</p><p>已在进行中的活动将平稳过渡，不受新规影响；新发起的活动需遵守上述新规。</p><h3 id="ambassador-计划与社区推广" tabindex="-1">Ambassador 计划与社区推广 <a class="header-anchor" href="#ambassador-计划与社区推广" aria-label="Permalink to &quot;Ambassador 计划与社区推广&quot;">​</a></h3><p>本次会议暂无相关更新。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>责任人</th><th>事项</th></tr></thead><tbody><tr><td>Ben</td><td>更新 ceph.io 商标相关使用条款与隐私政策（独立 PR）</td></tr><tr><td>Anthony + Ben</td><td>协作更新行为准则</td></tr><tr><td>Ben</td><td>跟进 Ceph Days 高质量 SVG 品牌图片制作</td></tr><tr><td>Anthony</td><td>更新 Ceph Days 相关指引文档并发布至社区</td></tr><tr><td>Manuel</td><td>继续推进剩余约 40 个文档 issue 的修复工作</td></tr><tr><td>全体</td><td>9 月 16 日前向 etherpad 提交 Q3 联席会议议题</td></tr><tr><td>全体</td><td>9 月第一周关注理事会选举提名启动</td></tr></tbody></table><h2 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h2><p>下次理事会公开会议定于 <strong>2026 年 9 月 22 日</strong>举行。</p>',39)])])}const _=a(o,[["render",n]]);export{c as __pageData,_ as default};
